 public void camera(float yaw,float pitch,float distance){this.yaw=Float.isFinite(yaw)?yaw:1.1f;this.pitch=Float.isFinite(pitch)?Math.max(.12f,Math.min(1.25f,pitch)):.48f;this.distance=Float.isFinite(distance)?Math.max(4.4f,Math.min(10,distance)):6.8f;update();}
 public void controls(ChannelSettings c,int part,boolean interior){lid=c.lid;size=c.bodySize;selection=part;inside=interior;update();}
 private void update(){state=new PianoCamera.State(yaw,pitch,distance,getWidth(),getHeight(),lid,size,selection,inside);requestRender();if(listener!=null)listener.cameraChanged();}
 protected void onSizeChanged(int w,int h,int ow,int oh){super.onSizeChanged(w,h,ow,oh);update();}
 public boolean onTouchEvent(android.view.MotionEvent e){pinch.onTouchEvent(e);int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){activePointer=e.getPointerId(0);downX=lastX=e.getX();downY=lastY=e.getY();moved=pinching=false;getParent().requestDisallowInterceptTouchEvent(true);return true;}if(a==MotionEvent.ACTION_POINTER_DOWN){moved=pinching=true;return true;}if(a==MotionEvent.ACTION_POINTER_UP){moved=true;if(e.getPointerId(e.getActionIndex())==activePointer){int i=e.getActionIndex()==0?1:0;activePointer=e.getPointerId(i);lastX=e.getX(i);lastY=e.getY(i);}return true;}
  if(a==MotionEvent.ACTION_MOVE){int i=e.findPointerIndex(activePointer);if(i<0)return true;float x=e.getX(i),y=e.getY(i);if(!pinch.isInProgress()&&!pinching){if(Math.abs(x-downX)+Math.abs(y-downY)>getResources().getDisplayMetrics().density*8)moved=true;if(moved){float density=getResources().getDisplayMetrics().density;yaw=PianoCamera.dragYaw(yaw,(x-lastX)/density);pitch=PianoCamera.dragPitch(pitch,(y-lastY)/density);update();}}lastX=x;lastY=y;return true;}
  if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);activePointer=-1;if(a==MotionEvent.ACTION_UP&&!moved&&!pinching){int picked=mesh.pick(state,e.getX(),e.getY());if(picked>=0&&listener!=null)listener.selected(picked);performClick();}pinching=false;return true;}return true;
 }
 public boolean performClick(){super.performClick();return true;}
 private int shader(int type,String source){int s=GLES20.glCreateShader(type);GLES20.glShaderSource(s,source);GLES20.glCompileShader(s);int[] ok=new int[1];GLES20.glGetShaderiv(s,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0){String log=GLES20.glGetShaderInfoLog(s);GLES20.glDeleteShader(s);throw new IllegalStateException(log);}return s;}
 public void onSurfaceCreated(GL10 gl,EGLConfig config){program=0;try{int v=shader(GLES20.GL_VERTEX_SHADER,VERTEX),f=shader(GLES20.GL_FRAGMENT_SHADER,FRAGMENT);int p=GLES20.glCreateProgram();GLES20.glAttachShader(p,v);GLES20.glAttachShader(p,f);GLES20.glLinkProgram(p);GLES20.glDeleteShader(v);GLES20.glDeleteShader(f);int[] ok=new int[1];GLES20.glGetProgramiv(p,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0){String log=GLES20.glGetProgramInfoLog(p);GLES20.glDeleteProgram(p);throw new IllegalStateException(log);}program=p;position=GLES20.glGetAttribLocation(p,"aPosition");normal=GLES20.glGetAttribLocation(p,"aNormal");color=GLES20.glGetAttribLocation(p,"aColor");part=GLES20.glGetAttribLocation(p,"aPart");matrix=GLES20.glGetUniformLocation(p,"uMatrix");angle=GLES20.glGetUniformLocation(p,"uAngle");scale=GLES20.glGetUniformLocation(p,"uScale");selected=GLES20.glGetUniformLocation(p,"uSelected");interior=GLES20.glGetUniformLocation(p,"uInterior");eye=GLES20.glGetUniformLocation(p,"uEye");GLES20.glEnable(GLES20.GL_DEPTH_TEST);}catch(Throwable ex){post(()->{if(listener!=null)listener.error("Visualização 3D indisponível nesta rota gráfica. Os controles de áudio continuam disponíveis.");});}GLES20.glClearColor(.956f,.952f,.923f,1);}
 public void onSurfaceChanged(GL10 gl,int w,int h){GLES20.glViewport(0,0,w,h);}
 private void attribute(int slot,int count,int offset){data.position(offset);GLES20.glVertexAttribPointer(slot,count,GLES20.GL_FLOAT,false,40,data);GLES20.glEnableVertexAttribArray(slot);}
 public void onDrawFrame(GL10 gl){GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);if(program==0)return;PianoCamera.State s=state;GLES20.glUseProgram(program);attribute(position,3,0);attribute(normal,3,3);attribute(color,3,6);attribute(part,1,9);GLES20.glUniformMatrix4fv(matrix,1,false,s.matrix,0);GLES20.glUniform1f(angle,s.angle);GLES20.glUniform1f(scale,s.scale);GLES20.glUniform1f(selected,s.selected);GLES20.glUniform1f(interior,s.interior?1:0);GLES20.glUniform3f(eye,-.8f+(float)(Math.sin(s.yaw)*Math.cos(s.pitch))*s.distance,-.05f+(float)Math.sin(s.pitch)*s.distance,(float)(Math.cos(s.yaw)*Math.cos(s.pitch))*s.distance);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,mesh.triangles*3);}
